.timer on
SELECT 'distinct id', COUNT(*) FROM (SELECT DISTINCT source_id, client_ip, client_name FROM queries WHERE NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626);
SELECT 'distinct id2', COUNT(*) FROM (SELECT DISTINCT client_ip, client_name, source_id FROM queries WHERE NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626);
EXPLAIN QUERY PLAN SELECT DISTINCT source_id, client_ip, client_name FROM queries WHERE NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626;
SELECT 'groupby id', COUNT(*) FROM (SELECT source_id, client_ip, client_name FROM queries WHERE NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626 GROUP BY 1,2,3);
SELECT 'distinct wide', COUNT(*) FROM (SELECT DISTINCT domain, client_ip, client_name, source_id, status, query_type FROM queries WHERE NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626);
